svg.script:

(function() {
  const svg = document.getElementById('piso09-marcha-svg');
  const path = svg.querySelector('#declinio-path');
  const pathActive = svg.querySelector('#declinio-path-active');
  const sliderHandle = svg.querySelector('#slider-handle');
  const selectionGlow = svg.querySelector('#selection-glow');
  const hotzone = svg.querySelector('#timeline-hotzone');
  const caseHighlight = svg.querySelector('#case-highlight-5');

  let currentYear = 0;
  let isDragging = false;

  const startX = 240;
  const stepX = 60;
  const yearsCount = 10;
  const nodeCoords = [];

  // Pesquisa binária exata para encontrar a coordenada Y no path dada a coordenada X
  function getYForX(targetX) {
    let min = 0;
    let max = path.getTotalLength();
    let point;
    for (let i = 0; i < 12; i++) {
      const percent = (min + max) / 2;
      point = path.getPointAtLength(percent);
      if (point.x < targetX) {
        min = percent;
      } else {
        max = percent;
      }
    }
    return point.y;
  }

  // Calcula as posições dos marcos biológicos e conectoras na curva
  function initCoordinates() {
    for (let year = 0; year <= yearsCount; year++) {
      const x = startX + year * stepX;
      const y = getYForX(x);
      nodeCoords.push({ x, y });

      const node = svg.querySelector('#node-' + year);
      if (node) {
        node.setAttribute('cx', x);
        node.setAttribute('cy', y);

        // Permite clicar nos próprios círculos da curva
        node.addEventListener('click', () => {
          updateYear(year);
        });
      }

      const conn = svg.querySelector('#connector-' + year);
      const label = svg.querySelector('#label-' + year);
      if (conn && label) {
        conn.setAttribute('x1', x);
        conn.setAttribute('y1', y);
        conn.setAttribute('x2', x);

        const labelY = y - 35;
        conn.setAttribute('y2', labelY + 8);
        label.setAttribute('x', x);
        label.setAttribute('y', labelY);

        label.style.cursor = 'pointer';
        label.addEventListener('click', () => {
          updateYear(year);
        });
      }
    }
  }

  // Atualiza a máquina de estados baseada no ano selecionado
  function updateYear(year) {
    currentYear = Math.max(0, Math.min(yearsCount, year));

    const activeX = startX + currentYear * stepX;
    const activeY = nodeCoords[currentYear].y;

    // 1. Deslocamento do cursor da timeline
    sliderHandle.setAttribute('cx', activeX);
    sliderHandle.setAttribute('aria-valuenow', currentYear);

    // 2. Revela a curva gradualmente até o ponto ativo
    const pathLength = path.getTotalLength();
    let min = 0;
    let max = pathLength;
    for (let i = 0; i < 12; i++) {
      const percent = (min + max) / 2;
      const pt = path.getPointAtLength(percent);
      if (pt.x < activeX) {
        min = percent;
      } else {
        max = percent;
      }
    }
    const activeLength = (min + max) / 2;
    pathActive.setAttribute('stroke-dasharray', activeLength + ' ' + pathLength);

    // 3. Posiciona o indicador pulsante
    selectionGlow.setAttribute('cx', activeX);
    selectionGlow.setAttribute('cy', activeY);
    selectionGlow.setAttribute('opacity', '1');

    // 4. Modifica opacidade e realce das marcas biológicas
    for (let i = 0; i <= yearsCount; i++) {
      const node = svg.querySelector('#node-' + i);
      const conn = svg.querySelector('#connector-' + i);
      const label = svg.querySelector('#label-' + i);

      if (node) {
        if (i === currentYear) {
          node.classList.add('active');
          node.setAttribute('r', '9');
        } else {
          node.classList.remove('active');
          node.setAttribute('r', '5.5');
        }

        if (i > currentYear) {
          node.style.opacity = '0.25';
          if (conn) conn.style.opacity = '0.05';
          if (label) label.style.opacity = '0.15';
        } else {
          node.style.opacity = '1';
          if (conn) conn.style.opacity = (i === currentYear) ? '0.8' : '0.25';
          if (label) label.style.opacity = (i === currentYear) ? '1' : '0.45';
        }
      }
    }

    // 5. Determina a fase ativa para atualização textual
    let activePhase = 0;
    if (currentYear === 0) activePhase = 0;
    else if (currentYear >= 1 && currentYear <= 3) activePhase = 1;
    else if (currentYear >= 4 && currentYear <= 6) activePhase = 2;
    else if (currentYear >= 7 && currentYear <= 8) activePhase = 3;
    else if (currentYear >= 9 && currentYear <= 10) activePhase = 4;

    for (let i = 0; i <= 4; i++) {
      const desc = svg.querySelector('#phase-' + i + '-desc');
      if (desc) {
        if (i === activePhase) {
          desc.style.display = 'block';
          desc.style.opacity = '1';
        } else {
          desc.style.display = 'none';
          desc.style.opacity = '0';
        }
      }
    }

    // 6. Alerta em Âmbar no caso clínico se o ano selecionado for o marco crítico da desorientação (Ano 5)
    if (caseHighlight) {
      if (currentYear === 5) {
        caseHighlight.classList.add('glow-amber');
      } else {
        caseHighlight.classList.remove('glow-amber');
      }
    }
  }

  // Converte coordenadas do mouse/pointer para o viewBox
  function getMouseX(e) {
    const p = svg.createSVGPoint();
    p.x = e.clientX;
    p.y = e.clientY;
    const svgP = p.matrixTransform(svg.getScreenCTM().inverse());
    return svgP.x;
  }

  function handlePointer(e) {
    const x = getMouseX(e);
    let year = Math.round((x - startX) / stepX);
    year = Math.max(0, Math.min(yearsCount, year));
    updateYear(year);
  }

  // Eventos de Scrubbing
  hotzone.addEventListener('pointerdown', function(e) {
    isDragging = true;
    hotzone.setPointerCapture(e.pointerId);
    handlePointer(e);
  });

  hotzone.addEventListener('pointermove', function(e) {
    if (isDragging) {
      handlePointer(e);
    }
  });

  hotzone.addEventListener('pointerup', function(e) {
    isDragging = false;
    hotzone.releasePointerCapture(e.pointerId);
  });

  hotzone.addEventListener('pointercancel', function(e) {
    isDragging = false;
  });

  // Acessibilidade por teclado
  sliderHandle.addEventListener('keydown', function(e) {
    if (e.key === 'ArrowRight' || e.key === 'ArrowUp') {
      updateYear(currentYear + 1);
      e.preventDefault();
    } else if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') {
      updateYear(currentYear - 1);
      e.preventDefault();
    }
  });

  // Inicialização da curva e sincronia das coordenadas
  initCoordinates();
  updateYear(0);
})();
